'use strict';
const $=s=>document.querySelector(s), icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',diary:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 7h8M8 11h8M8 15h5"/>',record:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/>',medication:'<path d="m8 4-4 4a5 5 0 0 0 7 7l4-4a5 5 0 0 0-7-7ZM7 5l7 7"/><path d="M16 15h5v6h-5z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',plan:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="M8 12h8M12 8v8"/>',reports:'<path d="M4 3v18h17M8 16v-4M13 16V7M18 16v-7"/>',privacy:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',wearable:'<rect x="6" y="6" width="12" height="12" rx="4"/><path d="M9 2h6v4M9 18v4h6v-4m-6-6 2 2 4-4"/>'};
const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.more}</svg>`;
const btn=(label,action,primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${label}</button>`;
const link=(label,to,primary=false)=>`<a class="btn ${primary?'primary':''}" href="#${to}">${label}</a>`;
const pill=(s,a=false)=>`<span class="pill ${a?'amber':''}">${s}</span>`;
const note=(s,a=false)=>`<div class="notice ${a?'amber':''}">${s}</div>`;
let role='Patient',current='home',record=null,selected=0,revoked=false,access=false,weekFilter=false;
const entries=[{date:'16 Nov 2026 · 14:32',source:'Patient reported',status:'Needs review',onset:'Unknown',end:'Unknown',activation:'16 Nov 2026, 14:32',check:'Unanswered',history:['Created by Alex · 16 Nov, 14:32'],notes:'Information left incomplete; review later.'},{date:'12 Nov 2026 · 09:15',source:'Caregiver observed',status:'Reviewed',onset:'09:10 (estimated)',end:'09:12 (estimated)',activation:'12 Nov 2026, 09:15',check:'Not shown',history:['Created by Sam · 12 Nov, 09:15'],notes:'Fictional observation; timing is an estimate.'},{date:'6 Nov 2026 · 18:40',source:'Patient reported',status:'Reviewed',onset:'Unknown',end:'Unknown',activation:'6 Nov 2026, 18:40',check:'Not shown',history:['Created by Alex · 6 Nov, 18:40'],notes:'No additional information recorded.'}];
let doses=['Pending','Pending'],sharing='Not created',privacyState='No request',device='Disconnected',deviceReview='Unconfirmed',recovery='Not completed';
function nav(){const items=[['home','Overview'],['diary','Episode diary'],['record','Record an episode'],['medication','Medication'],['plan','Action plan'],['reports','Reports'],['privacy','Privacy & access'],['more','Explore more']];$('#sideNav').innerHTML=items.map(([id,t])=>`<a href="#${id}" ${current===id?'class="active" aria-current="page"':''}>${ico(id)}${t}</a>`).join('');$('#bottomNav').innerHTML=[['home','Home'],['diary','Diary'],['record','Record'],['medication','Medication'],['more','More']].map(([id,t])=>`<a href="#${id}" ${current===id?'class="active" aria-current="page"':''}>${ico(id)}${t}</a>`).join('');}
const heading=(eyebrow,title,sub='',side='')=>`<div class="heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div>${side}</div>`;
const eventRows=()=>entries.map((e,i)=>`<div class="row"><div><h3>${e.date}</h3><p>${e.source} · ${e.onset==='Unknown'?'Timing unknown':'Estimated timing'}</p>${pill(e.status,e.status==='Needs review')}</div><button class="btn" data-event="${i}" aria-label="Review event ${e.date}">Review →</button></div>`).join('');
const chart=()=>`<div class="chart" role="img" aria-label="Illustrative recorded event counts: August 4, September 2, October 5, November 3. Incomplete months cannot be compared directly.">${[4,2,5,3].map((v,i)=>`<div class="barcol"><span>${v}</span><div class="bar" style="height:${v*19}px"></div><span>${['AUG','SEP','OCT','NOV*'][i]}</span></div>`).join('')}</div><p class="chart-note">Fixed illustration · *November is incomplete. Counts are records, not clinically confirmed seizures.</p>`;
function home(){if(role==='Clinician')return heading('CLINICIAN VIEW · SIMULATED ACCESS','A clearer view of care.','Alex Lane · fictional patient')+note('Example access scope: report and history review only. No clinical decisions or recommendations are generated.')+`<div class="grid"><section class="card"><h2>Patient-generated information</h2>${chart()}${link('Open clinical report','reports',true)}</section><section class="card"><h2>Review priorities</h2><p>One incomplete event has unknown timing and an unanswered check-in.</p>${link('Review source records','diary')}${note('Sharing access: illustrative only. No real patient connection.')}</section></div>`;
return heading(role==='Caregiver'?'CAREGIVER SPACE · SAM RIVERS':'TUESDAY, 17 NOVEMBER · DEMO DAY',role==='Caregiver'?'Care, together.':'Your day. At your pace.',role==='Caregiver'?'Supporting Alex Lane · fictional patient':'Welcome back, Alex. Make space for what matters.',pill('YOUR PERSONAL SPACE'))+(role==='Caregiver'?note(`Example permission: ${revoked?'revoked — diary assistance unavailable':'assisted recording and diary review'}. ${link('Review permissions','privacy')}`):'')+`<div class="grid"><div><section class="card hero"><div><p class="eyebrow">HERE WHEN YOU NEED IT</p><h2>One moment.<br>A little more clarity.</h2><p>Record what you know. You can fill in the details when you’re ready.</p></div>${link(role==='Caregiver'?'Record for Alex':'Record an episode','record') }</section><div class="stat-grid"><div class="stat"><strong>${entries.length}</strong><span>Example records</span></div><div class="stat"><strong>${entries.filter(e=>e.status==='Needs review').length}</strong><span>Awaiting review</span></div><div class="stat"><strong>—</strong><span>Clinical assessment</span></div></div><section class="card"><div class="section-title"><h2>Recent moments</h2><a href="#diary">View diary →</a></div>${role==='Caregiver'&&revoked?note('Diary access revoked in this demo.'):eventRows()}</section></div><div><section class="card"><div class="section-title"><h2>Today’s medication</h2>${ico('medication')}</div><p class="muted">Fictional schedule · 17 November</p><div class="row"><div><h3>Sample medicine A</h3><p>08:00 · dose intentionally omitted</p></div>${pill(doses[0],doses[0]==='Pending')}</div><div class="row"><div><h3>Sample medicine A</h3><p>20:00 · dose intentionally omitted</p></div>${pill(doses[1],doses[1]==='Pending')}</div><div class="actions">${link('View schedule','medication')}</div></section><section class="card"><p class="eyebrow">YOUR CARE, IN ONE PLACE</p><h2>A plan you can find.</h2><p class="muted">See how a personal action plan could be accessed and reviewed.</p>${link('Explore sample plan →','plan')}</section><section class="card" style="background:var(--soft)"><h2>No rush to finish.</h2><p class="muted">A recovery check-in is optional. Return whenever you feel ready.</p>${link('Open check-in','recovery')}</section></div></div>`;}
function recorder(){if(role==='Clinician'||(role==='Caregiver'&&revoked))return heading('PERMISSION BOUNDARY','Recording unavailable','This demonstration role does not have recording permission.')+link('Return to overview','home');if(!record)return heading('SMART EPISODE RECORDER','Start with what you know.','This records a demo interaction, not a detected seizure.')+`<section class="card recordbox"><h2>Choose a candidate interaction</h2><p class="muted">Neither method is an approved default. Both need accessibility evaluation.</p><label class="field">Activation method<select id="method"><option value="direct">Single tap / keyboard activation</option><option value="confirm">Tap, then confirm</option></select></label><button class="recordcircle" data-action="begin" aria-label="Start demo recording">${ico('record')}<span>Start recording</span></button>${note('Activation time is when this control is used. Seizure onset and end remain unknown until explicitly estimated.')}${link('Log a past fictional event','past')}</section>`;
return heading('RECORDING SESSION',record.state==='active'?'Recording is active.':record.state==='unfinished'?'Recording unfinished.':'Recording stopped.','Recorder activity does not establish whether a seizure is occurring.')+`<section class="card recordbox">${pill(record.state==='active'?'Recorder active':record.state==='unfinished'?'Status unknown':'Recorder stopped',record.state==='unfinished')}<div class="timer" id="timer">${elapsed()}</div><p class="center muted">Recorder elapsed time · not seizure duration</p><div class="row"><span>Activation timestamp</span><strong>${record.activation}</strong></div><div class="row"><span>Seizure onset / end</span><strong>Unknown / unknown</strong></div>${record.check?note('Check-in unanswered. Seizure status remains unknown. No one has been notified.',true):''}<div class="actions">${record.state==='active'?btn('Stop recorder','stop',true)+btn('Show sample check-in','check')+btn('Leave unfinished','unfinished'):btn('Save demo record','save',true)}</div>${note('No emergency assistance is requested by any action in this prototype.')}</section>`;}
function elapsed(){if(!record)return '00:00';let s=Math.floor(((record.stop||Date.now())-record.start)/1000);return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;}
function detail(){let e=entries[selected];return heading('EPISODE DETAIL',e.date,e.source+' · synthetic record')+`<div class="grid"><section class="card"><h2>What was recorded</h2><div class="row"><span>Activation</span><strong>${e.activation}</strong></div><div class="row"><span>Estimated onset</span><strong>${e.onset}</strong></div><div class="row"><span>Estimated end</span><strong>${e.end}</strong></div><div class="row"><span>Check-in</span><strong>${e.check}</strong></div><p class="muted" style="margin-top:20px">${e.notes}</p>${note('No clinical classification assigned. Recorder elapsed time is not used as seizure duration.')}<div class="actions">${role==='Clinician'?'':btn('Apply fictional timing correction','correct')+btn('Mark accidental','accidental')}${link('Recovery check-in','recovery')}${link('Back to diary','diary')}</div></section><section class="card"><h2>Record provenance</h2>${e.history.map(h=>`<div class="row"><p>${h}</p></div>`).join('')}${note('Corrections retain original observations in this session. Nothing is silently deleted.')}</section></div>`;}
function medication(){return heading('MEDICATION','A little everyday support.','Example schedule only. No dosage or treatment advice.')+`<div class="grid"><section class="card"><h2>Tuesday, 17 November</h2>${doses.map((s,i)=>`<div class="row"><div><h3>Sample medicine A · ${i?'20:00':'08:00'}</h3><p>Dose omitted from fictional plan</p>${pill(s,s==='Pending')}<div class="actions">${btn('Taken',`dose${i}taken`)}${btn('Missed',`dose${i}missed`)}</div></div></div>`).join('')}${note('Reminder preview: “You have a medication diary entry to review.” No reminder is scheduled or delivered.')}</section><section class="card"><h2>History & observations</h2><p>${doses.filter(d=>d==='Taken').length} taken · ${doses.filter(d=>d==='Missed').length} missed · ${doses.filter(d=>d==='Pending').length} pending</p><p class="muted">Illustrative completion only; not an adherence assessment.</p><label class="field">Fictional side-effect entry<select id="symptom"><option>Not sure</option><option>Example: tiredness</option><option>Prefer not to say</option></select></label>${btn('Save example observation','sideeffect')}${link('Sample rescue plan concept','plan')}<div id="sideeffectResult"></div></section></div>`;}
function privacy(){return heading('PRIVACY & ACCESS','Your information. Your choice.','Every action here affects this demo session only.')+`<div class="grid"><section class="card"><h2>People with example access</h2><div class="row"><div><h3>Sam Rivers · caregiver</h3><p>Assisted recording & diary · fictional scope</p>${pill(revoked?'Revoked (demo)':'Active (demo)',revoked)}</div>${btn(revoked?'Restore demo':'Review & revoke','revoke')}</div><div class="row"><div><h3>Clinician report</h3><p>${sharing} · demo only</p></div>${link('Sharing preview','sharing')}</div><div class="actions">${btn('Preview invitation','invite')}</div>${note('Child, guardian and witness access rules remain research decisions.')}</section><section class="card"><h2>Data controls</h2><p id="privacyStatus">${privacyState}</p><div class="actions">${btn('Request export','export')}${btn('Request deletion','delete')}</div>${note('No real account, export job or deletion request is created. Retention and deletion policy is unresolved.')}</section><section class="card"><h2>Example access history</h2><div class="row"><div><h3>Sam viewed shared diary</h3><p>16 Nov · 14:50 · fictional audit event</p></div></div><div class="row"><div><h3>Alex reviewed a record</h3><p>16 Nov · 15:20 · fictional audit event</p></div></div>${revoked?'<p>Caregiver access revoked in this demo session.</p>':''}</section></div>`;}
function reports(){return heading('REPORTS & INSIGHTS','Patterns, with perspective.','Fictional patient-generated information · no clinical interpretation')+`<div class="grid"><section class="card"><h2>Recorded events</h2>${chart()}<details><summary>View accessible data table</summary><table><thead><tr><th>Month</th><th>Records</th></tr></thead><tbody>${['August:4','September:2','October:5','November (partial):3'].map(x=>`<tr><td>${x.split(':')[0]}</td><td>${x.split(':')[1]}</td></tr>`).join('')}</tbody></table></details></section><section class="card"><h2>Report overview</h2><p>Alex Lane · fictional identity</p><p>${entries.length} session records · ${entries.filter(e=>e.onset==='Unknown').length} with unknown onset</p><p>Estimated durations are shown only when both endpoints are provided. No population risk or treatment score.</p>${link('Preview clinical report','report-preview',true)}</section><section class="card"><h2>Possible patterns</h2><p class="muted">Example note: “Sleep was mentioned alongside two diary entries.”</p>${note('An association does not establish a trigger or cause. This example is not calculated from session data.')}${link('Calendar view','calendar')}</section><section class="card"><h2>Medication diary summary</h2><p>${doses.filter(d=>d==='Taken').length} of 2 example entries marked taken.</p><p class="muted">Pending entries are not assumed missed. This is not a treatment assessment.</p>${link('Time-limited sharing concept','sharing')}</section></div>`;}
function more(){return heading('EXPLORE','Care, from every angle.','Browse the full vision and the decisions still ahead.')+`<section class="card viewlist">${[['plan','Action plan'],['reports','Reports & insights'],['privacy','Privacy & access'],['wearable','Wearable concept'],['recovery','Recovery check-in'],['settings','Accessibility & appearance'],['young','Child & teen concept'],['scenarios','Offline & error scenarios'],['guide','Prototype guide & decisions'],['welcome','Welcome & onboarding']].map(([id,t])=>link(t+' →',id)).join('')}</section>`;}
function render(focus=false){current=location.hash.slice(1)||'home';if(current==='main'){current='home';}nav();$('#breadcrumb').textContent=`${role} space / ${current.replaceAll('-',' ')}`;let html='';switch(current){case'home':html=home();break;case'record':html=recorder();break;case'confirm':html=heading('CANDIDATE INTERACTION','Ready to start?','This confirmation method is for comparison in usability research.')+`<section class="card">${btn('Confirm demo recording','start',true)} ${link('Cancel','record')}</section>`;break;case'check':html=heading('SAMPLE CHECK-IN','Would you like to add an update?','Example wording and timing are not clinically approved.')+`<section class="card recordbox"><p>The recorder is preserved while this prompt is open.</p>${note('Not responding gives no information about seizure continuation or completion.',true)}<div class="actions">${btn('Leave unanswered','unanswered',true)}${link('Return to recorder','record')}${btn('Stop recorder','stop')}</div><p class="muted">No caregiver or emergency notification will be sent.</p></section>`;break;case'saved':html=heading('DEMO RECORD SAVED','The details can wait.','Seizure timing remains unknown unless explicitly provided.')+`<section class="card recordbox">${pill('Saved in this session')}<div class="actions">${link('Optional recovery check-in','recovery',true)}${link('Review later · open diary','diary')}</div></section>`;break;case'recovery':html=heading('RECOVERY CHECK-IN','Take your time.','Optional questions. You can skip everything and return later.')+`<section class="card recordbox"><label class="field">Example wellbeing response<select id="wellbeing"><option>Not sure</option><option>Would like support</option><option>Prefer not to say</option></select></label><label class="field">Example symptom response<select><option>Leave unknown</option><option>Example: tiredness</option><option>Prefer not to say</option></select></label>${note('This does not assess clinical stability or readiness for activity.')}<div class="actions">${btn('Save example check-in','recover',true)}${btn('Preview caregiver assistance','assist')}${btn('Review reminder concept','reminder')}${link('Skip for now','diary')}</div><p class="muted">Current demo status: ${recovery}</p></section>`;break;case'diary':html=heading('EPISODE DIARY','Your story, at your pace.','Unknown details are welcome. Nothing needs to be perfect.',link('Calendar','calendar'))+`<section class="card">${role==='Caregiver'&&revoked?note('Demo permission denied. Caregiver access has been revoked.'):eventRows()}<div class="actions">${link('Record an episode','record',true)}${link('Possible duplicate example','duplicate')}</div></section>`;break;case'detail':html=(role==='Caregiver'&&revoked)?note('Access denied in this demo.'):detail();break;case'calendar':html=heading('DIARY CALENDAR','November 2026','Underlined dates contain fictional events.')+`<section class="card"><div class="calendar">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}${Array(6).fill('<span></span>').join('')}${Array.from({length:30},(_,i)=>`<button data-day="${i+1}" ${[6,12,16].includes(i+1)?'class="event"':''} aria-label="November ${i+1}${[6,12,16].includes(i+1)?', example event':''}">${i+1}</button>`).join('')}</div><div id="dayResult" class="notice">Select a date to browse.</div></section>`;break;case'medication':html=medication();break;case'privacy':html=privacy();break;case'reports':html=reports();break;case'plan':html=heading('SEIZURE ACTION PLAN','A plan, close at hand.','Display concept only · no individualized treatment instructions')+`<section class="card"><div class="section-title"><h2>Alex’s sample plan</h2>${pill('NOT CLINICALLY APPROVED',true)}</div><div class="row"><span>Source</span><strong>Fictional demonstration</strong></div><div class="row"><span>Version</span><strong>Example 0.1</strong></div><div class="row"><span>Verification / review</span><strong>Not verified</strong></div><details open><summary>What this plan could contain</summary><p>Authorized clinical instructions, relevant contacts, review date and version history would appear here after governance is agreed.</p></details><details><summary>Rescue-medication plan concept</summary><p>No medicine, dose, route or timing instructions are provided. Authorized source and content governance remain unresolved.</p></details>${note('This sample cannot be used during an actual emergency. The prototype does not contact anyone.',true)}${link('Read unresolved decisions','guide')}</section>`;break;case'wearable':html=heading('FUTURE CONNECTIONS','Another piece of the picture.','Concept only · no device discovery or monitoring')+`<div class="grid"><section class="card"><p class="eyebrow">FICTIONAL WEARABLE</p><h2>Demo wrist device</h2><div class="recordcircle">${ico('wearable')}</div><p class="center">${device}</p><div class="actions">${btn('Simulate connection','connect',true)}${btn('Simulate disconnect','disconnect')}${btn('Unsupported device','unsupported')}</div>${note('No named device support or detection accuracy is claimed. Permissions shown are illustrative.')}</section><section class="card"><h2>Possible-event review</h2><p>Example device signal · 17 Nov, 10:24</p>${pill(deviceReview,true)}${note('A device-suspected signal is not a confirmed seizure. Devices may miss events or raise false alerts.')}<div class="actions">${link('Review possible event','device-review')}</div></section></div>`;break;case'device-review':html=heading('UNCONFIRMED DEVICE SIGNAL','Review what you know.','This is a simulated notification, not detection.')+`<section class="card"><p>Source: fictional wearable · Example signal at 10:24</p>${pill(deviceReview,true)}<div class="actions">${btn('Keep uncertain','uncertain')}${btn('Mark not an episode','dismiss-device')}${btn('Create suspected diary entry','device-save',true)}${link('Compare possible duplicate','duplicate')}</div></section>`;break;case'duplicate':html=heading('RECORD RECONCILIATION','Could these be related?','Two fictional sources may refer to one event. No automatic merge.')+`<section class="card"><div class="row"><span>Patient report</span><span>10:25 · estimated</span></div><div class="row"><span>Device-suspected signal</span><span>10:24 · unconfirmed</span></div>${note('Original source records would remain available. Reconciliation rules require further review.')}<div class="actions">${btn('Preview a linked pair','link-pair')}${link('Keep separate','diary')}</div></section>`;break;case'sharing':html=heading('REPORT SHARING','Access with boundaries.','Time-limited sharing concept · no link is sent or activated')+`<section class="card"><label class="field">Example expiry<select id="expiry"><option>7 days (illustration)</option><option>24 hours (illustration)</option></select></label><p>Scope: fictional report only. Recipient identity and verification rules remain undecided.</p><p>Status: ${sharing}</p><div class="actions">${btn('Create demo sharing state','share',true)}${btn('Revoke demo sharing','unshare')}</div></section>`;break;case'report-preview':html=heading('CLINICAL REPORT PREVIEW','Alex Lane','FICTIONAL REPORT · NOT FOR CLINICAL USE')+`<section class="card"><h2>Patient-generated episode summary</h2><p>${entries.length} records. Unknown values retained. Sources: patient reports, caregiver observations and any simulated device entries.</p>${eventRows()}${note('No diagnosis, treatment advice or validated clinical assessment. Charts elsewhere are fixed illustrations.')}<div class="actions">${btn('Preview PDF-export outcome','pdf')}${link('Sharing options','sharing')}</div></section>`;break;case'settings':html=heading('ACCESSIBILITY & APPEARANCE','Comfort, by design.','The prototype follows your device’s light or dark appearance.')+`<section class="card"><h2>Appearance follows your phone</h2><p>Change your device appearance to preview Modern Wellness or Premium Midnight. There is no saved manual theme override.</p><h2>Interaction support</h2><ul class="checklist"><li>Readable text, responsive layouts and labelled controls.</li><li>Keyboard focus indicators and a skip-to-content link.</li><li>No flashing, autoplay, decorative animation or sound.</li><li>Status uses words as well as colour.</li><li>Use browser text scaling or zoom as needed.</li></ul>${note('Accessibility review is initial and incomplete. Screen-reader, motor-access and lived-experience testing are still required. No full-compliance claim.')}${link('Compare recorder activation methods','record')}</section>`;break;case'young':html=heading('CHILD & TEEN PREVIEW','Growing independence.','Concept preview · no real age or guardian information collected')+`<section class="card"><h2>A simpler diary</h2><p>“Add what you remember. It’s okay if you’re not sure.”</p>${link('Explore optional check-in','recovery')}${note('Who can view, edit, consent or revoke access is unresolved. No automatic guardian access is assumed.',true)}<h3>Proposed research areas</h3><p class="muted">Age-appropriate language, safeguarding, consent and evolving autonomy.</p></section>`;break;case'scenarios':html=heading('RESILIENCE SCENARIOS','When things don’t go to plan.','Manually selected demonstrations, not real sync or service states.')+`<section class="card"><div class="viewlist">${btn('Offline example','offline')}${btn('Save error example','error')}${btn('Permission denied','denied')}${btn('Empty diary','empty')}</div><div id="scenario" class="notice">Choose a scenario.</div></section>`;break;case'welcome':html=heading('WELCOME TO EPILEPSY CARE','A little clarity. Every day.','A fictional-data prototype built around recording, reflection and support.')+`<section class="card"><h2>Explore a perspective</h2><p>Use the role selector to explore patient, caregiver and clinician journeys. No sign-in or personal information is needed.</p>${note('By exploring, you are not enrolling in research or consenting to data collection. Participant research needs a separate approved consent process.')}<div class="actions">${link('Explore patient overview','home',true)}${link('Read prototype guide','guide')}</div></section>`;break;case'past':html=heading('PAST EVENT CONCEPT','Unknown is a valid answer.','Create a fictional historical entry without inventing onset or duration.')+`<section class="card">${btn('Add fictional past event · timing unknown','past-save',true)}</section>`;break;case'guide':html=guide();break;case'more':html=more();break;default:html=heading('PAGE UNAVAILABLE','Let’s get you back.','This destination is not part of the prototype.')+link('Return home','home');}if(role==='Caregiver'&&revoked&&['diary','detail','calendar','reports','report-preview','plan','recovery','device-review'].includes(current)){html=heading('DEMO PERMISSION BOUNDARY','Access has been revoked.','This caregiver cannot view patient information in the demo.')+link('Review permissions','privacy');}$('#main').innerHTML=html;if(role==='Clinician'){$('#main').querySelectorAll('button[data-action]').forEach(b=>{if(!['pdf','share','unshare'].includes(b.dataset.action)){b.disabled=true;b.title='Read-only clinician demonstration';}});}if(focus){$('#main').focus();window.scrollTo(0,0);}}
function guide(){return heading('PROTOTYPE GUIDE','The vision. The boundaries.','PRD v0.1 · 17 November 2026 · discovery baseline')+`<section class="card"><h2>Start exploring</h2><div class="viewlist">${link('A · Record and recover','record')}${link('B · Caregiver: choose role above','home')}${link('C · Review and correct history','diary')}${link('D · Medication diary','medication')}${link('E · Clinician report','reports')}${link('F · Wearable concept','wearable')}${link('G · Privacy management','privacy')}</div></section><section class="card"><h2>Design decisions & open questions</h2><p><b>Confirmed:</b> full-vision demo, fictional data, optional recovery and device-following appearance.</p><p><b>Proposed:</b> single-tap and tap-confirm activation candidates; layouts, sample permissions and sample check-in wording.</p><p><b>Scope clarification:</b> “request assistance”, “export”, “delete” and “share” show simulated outcomes only. Wearable support is unnamed and fictional. Child/teen screens demonstrate language, not settled access policy.</p>${['SAFE-01 / 02 · Seizure classification and uncertain-event terminology','SAFE-03 · Default activation and accessibility evaluation','SAFE-04 / 05 · Check-in timing, questions, notifications and escalation','SAFE-06 · Unregistered witness access','SAFE-07 / 08 · Action-plan verification and rescue-content governance','SAFE-09 · Child and guardian permissions','SAFE-10 / 11 · Wearable evidence and future AI medical functionality','SAFE-12 · Production retention, deletion and UK privacy review'].map(s=>`<details><summary>${s}</summary><p>Research required. Not resolved or implemented as clinical functionality in this prototype.</p></details>`).join('')}</section><section class="card"><h2>Initial accessibility review</h2><p>Implemented: semantic buttons, labelled inputs, visible focus, keyboard operation, minimum 44px principal controls, responsive reflow, system themes, no flashing or motion.</p><p>Still to validate: full WCAG 2.2 review, screen readers, browser text scaling, post-episode cognitive load, one-handed use and activation alternatives with participants.</p><h2>Research boundaries</h2><p>Use fictional tasks only. Do not imitate or induce seizures. Participation must be voluntary, skippable and supported by a separate consent and research-data plan.</p><p>No analytics, clinical accounts, backend synchronization, monitoring or external integrations are included.</p></section>`;}
function go(s){if(location.hash==='#'+s)render();else location.hash=s;}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
function start(){record={ownerRole:role,start:Date.now(),activation:new Date().toLocaleString('en-GB'),state:'active',check:false};go('record');}
document.addEventListener('click',e=>{const ev=e.target.closest('[data-event]');if(ev){selected=Number(ev.dataset.event);go('detail');return;}const day=e.target.closest('[data-day]');if(day){const i={16:0,12:1,6:2}[day.dataset.day];$('#dayResult').innerHTML=i===undefined?'No fictional records on this date.':`Example event on ${day.dataset.day} November. <button class="btn" data-event="${i}">Review event →</button>`;return;}const b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a.startsWith('dose')){doses[Number(a[4])]=a.endsWith('taken')?'Taken':'Missed';render();toast('Example medication entry updated.');return;}switch(a){case'begin':$('#method').value==='confirm'?go('confirm'):start();break;case'start':start();break;case'stop':if(record){record.state='stopped';record.stop=Date.now();}go('record');break;case'check':go('check');break;case'unanswered':if(record)record.check=true;go('record');break;case'unfinished':record.state='unfinished';record.stop=Date.now();record.check=true;render();break;case'save':entries.unshift({date:record.activation,activation:record.activation,source:record.ownerRole==='Caregiver'?'Caregiver observed':'Patient reported',status:'Needs review',onset:'Unknown',end:'Unknown',check:record.check?'Unanswered':'Not shown',history:[`Created by ${record.ownerRole} · activation ${record.activation}`,`Recorder ${record.state}; elapsed ${elapsed()} — not seizure duration`],notes:'Fictional recording interaction. Clinical status unknown.'});record=null;go('saved');break;case'correct':let en=entries[selected];en.history.push(`Previous timing retained: onset ${en.onset}, end ${en.end}. Applied fictional estimated timing 14:30–14:31.`);en.onset='14:30 (fictional estimate)';en.end='14:31 (fictional estimate)';en.status='Edited · estimate';render();break;case'accidental':entries[selected].status='Marked accidental';entries[selected].history.push('Marked accidental in demo. Original record retained.');render();break;case'recover':recovery='Example check-in saved';render();toast('Optional demo response saved. No clinical assessment.');break;case'assist':toast('Assistance request preview only. Nobody has been contacted.');break;case'reminder':toast('Reminder concept: review your diary later. Nothing has been scheduled.');break;case'sideeffect':$('#sideeffectResult').textContent='Saved example: '+$('#symptom').value;break;case'revoke':if(revoked){revoked=false;render();}else{b.outerHTML=note('Revoke Sam’s access in this demo? No real permission changes.')+btn('Confirm demo revocation','revoke-confirm');}break;case'revoke-confirm':revoked=true;render();break;case'invite':toast('Invitation preview only: example caregiver access. No invitation sent.');break;case'export':privacyState='Export request pending (simulation)';render();break;case'delete':b.outerHTML=note('Preview a deletion request? Records will remain in this demo; no real deletion occurs.',true)+btn('Confirm simulated request','delete-confirm');break;case'delete-confirm':privacyState='Deletion request pending (simulation) · no data deleted';render();break;case'share':sharing='Active for '+$('#expiry').value.replace(' (illustration)','')+' (simulated; no live link)';render();break;case'unshare':sharing='Revoked (simulation)';render();break;case'connect':device='Connected (simulation only)';render();break;case'disconnect':device='Disconnected';render();break;case'unsupported':device='Unsupported example device';render();break;case'uncertain':deviceReview='Unconfirmed · review deferred';render();break;case'dismiss-device':deviceReview='Marked not an episode (demo)';render();break;case'device-save':if(deviceReview.includes('Added')){toast('The suspected entry already exists in this session.');break;}entries.unshift({date:'17 Nov 2026 · 10:24',source:'Device suspected · unconfirmed',status:'Needs review',onset:'Unknown',end:'Unknown',activation:'No manual activation',check:'Not applicable',history:['Simulated device signal · 10:24','Added for manual review; not clinically confirmed'],notes:'Fictional possible event; detection did not occur.'});deviceReview='Added for review · unconfirmed';go('diary');break;case'link-pair':toast('Linked-pair preview: both source records retained; no automatic merge.');break;case'pdf':toast('PDF export simulated: a fictional report would be prepared. No file generated.');break;case'offline':$('#scenario').innerHTML='Offline demonstration: no cloud sync. An unfinished recorder remains available during this page session. Reloading clears demo changes. '+link('Return to recorder','record');break;case'error':$('#scenario').innerHTML='Example save error: draft retained in this session. '+btn('Retry simulated save','retry');break;case'retry':$('#scenario').textContent='Simulated retry complete. No external storage was contacted.';break;case'denied':$('#scenario').textContent='Permission denied example. The requested diary is unavailable to this role.';break;case'empty':$('#scenario').innerHTML='No events in this example view. '+link('Create a demo recording','record');break;case'past-save':entries.unshift({date:'10 Nov 2026 · time unknown',source:'Patient reported retrospectively',status:'Needs review',activation:'No live recorder activation',onset:'Unknown',end:'Unknown',check:'Not applicable',history:['Fictional retrospective entry created'],notes:'Historical date is illustrative. Onset and end unknown.'});go('diary');break;}});
$('#role').addEventListener('change',e=>{role=e.target.value;go('home');});window.addEventListener('hashchange',()=>render(true));setInterval(()=>{if($('#timer'))$('#timer').textContent=elapsed();},1000);render();
